pub fn numpy_matrix_transpose(x: Vec<Vec<f32>>) -> Vec<Vec<f32>> {
    // Problem statement guarantees non-empty and rectangular, but we assert to avoid panics
    // on malformed input and to make assumptions explicit.
    assert!(!x.is_empty(), "matrix must have at least one row");
    let rows = x.len();
    let cols = x[0].len();
    assert!(cols > 0, "matrix must have at least one column");

    for (i, row) in x.iter().enumerate() {
        assert!(
            row.len() == cols,
            "matrix must be rectangular: row {} has len {}, expected {}",
            i,
            row.len(),
            cols
        );
    }

    // Allocate result with shape (cols x rows).
    let mut result = vec![vec![0.0f32; rows]; cols];

    // Fill transpose: result[c][r] = x[r][c]
    for r in 0..rows {
        for c in 0..cols {
            result[c][r] = x[r][c];
        }
    }

    result
}